pub struct Worker {
    store: Store,
    drivers: HashMap<String, Arc<DockerDriver>>,
    registration: WorkerRegistration,
    locks: Mutex<HashMap<Uuid, Weak<Mutex<()>>>>,
    concurrency: Arc<Semaphore>,
    cancellations: Mutex<HashMap<Uuid, Instant>>,
    context_closures: Mutex<HashMap<Uuid, Instant>>,
    artifacts: goldenhoop_artifacts::BlobStore,
    artifact_concurrency: Arc<Semaphore>,
    network_controller_image: Option<String>,
    network_options: Option<NetworkOptions>,
    network_tasks: Mutex<HashMap<Uuid, network_policy::NetworkTask>>,
}

impl Worker {
    pub async fn new(
        store: Store,
        agent_image: String,
        kernel_probe_image: Option<String>,
        allow_runc_development: bool,
        endpoint: String,
        artifacts: goldenhoop_artifacts::BlobStore,
        network: NetworkSetup,
    ) -> Result<Arc<Self>, ApiError> {
        let NetworkSetup {
            controller_image: network_controller_image,
            options: network_options,
        } = network;
        if artifacts.installation_id() != store.installation_id() {
            return Err(ApiError::new(
                ErrorCode::InvalidRequest,
                "artifact storage installation identity mismatch",
            ));
        }
        store.bind_artifact_backend(artifacts.binding()).await?;
        if let Some(image) = &network_controller_image {
            goldenhoop_docker::DockerControllerProvider::connect(image).await?;
        }
        if let Some(options) = &network_options {
            if network_controller_image.is_none() {
                return Err(ApiError::new(
                    ErrorCode::InvalidRequest,
                    "protected networking requires a pinned controller image",
                ));
            }
            options.validate()?;
            store.bind_network_operator(&options.operator).await?;
        }
        let mut drivers = HashMap::new();
        let mut profiles = Vec::new();
        for profile in [DockerProfile::Gvisor, DockerProfile::RuncDevelopment] {
            let driver = Arc::new(
                DockerDriver::connect(DockerConfig {
                    installation_id: store.installation_id(),
                    agent_image: agent_image.clone(),
                    profile,
                    allow_runc_development,
                })
                .await?,
            );
            let mut observed = driver.probe().await;
            if observed.availability == Availability::Available
                && let Some(image) = &kernel_probe_image
            {
                observed = match driver.probe_code_contexts(image).await {
                    Ok(profile) => profile,
                    Err(error) => {
                        report("kernel_probe_failed", &error);
                        driver.profile_snapshot().await
                    }
                };
            }
            if observed.availability == Availability::Available {
                match driver.probe_isolated_sandboxes().await {
                    Ok(()) => {
                        observed.capabilities.insert(Capability::IsolatedSessions);
                    }
                    Err(error) => report("isolated_runtime_probe_failed", &error),
                }
            }
            profiles.push(observed);
            drivers.insert(profile.id().into(), driver);
        }
        let artifact_support = match artifacts.probe().await {
            Ok(()) => true,
            Err(error) => {
                report("artifact_storage_probe_failed", &error);
                false
            }
        };
        if artifact_support {
            for profile in &mut profiles {
                if profile.availability == Availability::Available
                    && profile.capabilities.contains(&Capability::Files)
                {
                    profile.capabilities.insert(Capability::Artifacts);
                }
            }
        }
        if network_options.is_some() {
            for profile in &mut profiles {
                if profile.availability == Availability::Available {
                    // Internal candidate only. The public registration remains
                    // unavailable until real application and cleanup succeed.
                    profile.capabilities.insert(Capability::NetworkPolicy);
                }
            }
        }
        let registration = WorkerRegistration {
            id: Uuid::new_v4(),
            endpoint,
            token: format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple()),
            heartbeat: Utc::now(),
            profiles,
        };
        let mut pending = registration.clone();
        if network_options.is_some() {
            for profile in &mut pending.profiles {
                profile.availability = Availability::Unavailable;
                profile.capabilities.remove(&Capability::NetworkPolicy);
                profile.reason = Some("protected network availability probe is in progress".into());
            }
        }
        store.register_worker(&pending).await?;
        let mut worker = Arc::new(Self {
            store,
            drivers,
            registration,
            locks: Mutex::new(HashMap::new()),
            concurrency: Arc::new(Semaphore::new(4)),
            cancellations: Mutex::new(HashMap::new()),
            context_closures: Mutex::new(HashMap::new()),
            artifacts,
            artifact_concurrency: Arc::new(Semaphore::new(2)),
            network_controller_image,
            network_options,
            network_tasks: Mutex::new(HashMap::new()),
        });
        if worker.network_options.is_some() {
            let (stop, receive) = watch::channel(false);
            let store = worker.store.clone();
            let heartbeat = tokio::spawn(network_probe::pending_heartbeat(store, pending, receive));
            let result = worker.probe_network_profiles(&agent_image).await;
            let _ = stop.send(true);
            heartbeat.await.map_err(|_| {
                ApiError::new(
                    ErrorCode::BackendUnavailable,
                    "network probe heartbeat did not settle",
                )
            })??;
            let profiles = result?;
            let owned = Arc::get_mut(&mut worker).ok_or_else(|| {
                ApiError::new(
                    ErrorCode::Internal,
                    "network probe retained worker ownership",
                )
            })?;
            owned.registration.profiles = profiles;
            owned.registration.heartbeat = Utc::now();
            owned.store.register_worker(&owned.registration).await?;
        }
        Ok(worker)
    }

    pub fn router(self: &Arc<Self>) -> Result<Router, ApiError> {
        let auth = BearerAuth::new(&self.registration.token)?;
        Ok(Router::new()
            .route("/internal/files", post(files))
            .route("/internal/diagnostics", post(diagnostics))
            .route("/internal/artifact-content", post(artifacts::content))
            .fallback(not_found)
            .layer(DefaultBodyLimit::max(24 * 1024 * 1024))
            .layer(ConcurrencyLimitLayer::new(16))
            .layer(middleware::from_fn_with_state(auth, authenticate))
            .with_state(self.clone()))
    }

    async fn lock(&self, id: Uuid) -> Arc<Mutex<()>> {
        let mut locks = self.locks.lock().await;
        locks.retain(|_, lock| lock.strong_count() > 0);
        if let Some(lock) = locks.get(&id).and_then(Weak::upgrade) {
            return lock;
        }
        let lock = Arc::new(Mutex::new(()));
        locks.insert(id, Arc::downgrade(&lock));
        lock
    }

    pub async fn run(self: Arc<Self>, mut shutdown: watch::Receiver<bool>) {
        let mut tasks = JoinSet::new();
        let mut offset = 0_usize;
        let mut artifact_offset = 0_usize;
        loop {
            if *shutdown.borrow() {
                break;
            }
            match self.store.work().await {
                Ok(mut work) => {
                    if !work.is_empty() {
                        let start = offset % work.len();
                        work.rotate_left(start);
                        offset = offset.wrapping_add(4);
                    }
                    for stored in work {
                        let Ok(permit) = self.concurrency.clone().try_acquire_owned() else {
                            break;
                        };
                        let Ok(guard) = self.lock(stored.sandbox.id).await.try_lock_owned() else {
                            continue;
                        };
                        let worker = self.clone();
                        let id = stored.sandbox.id;
                        tasks.spawn(async move {
                            let _guard = guard;
                            let _permit = permit;
                            if let Err(error) = worker.reconcile(id).await {
                                if let Err(persist) = worker.record_error(id, &error).await {
                                    report("observation_persist_failed", &persist);
                                }
                                report("reconciliation_failed", &error);
                            }
                        });
                    }
                }
                Err(error) => report("work_scan_failed", &error),
            }
            while let Some(result) = tasks.try_join_next() {
                if result.is_err() {
                    eprintln!("{{\"event\":\"reconciliation_task_failed\"}}");
                }
            }
            if let Err(error) = self.store.settle_network_policy_changes().await {
                report("network_policy_change_settlement_failed", &error);
            }
            match self.store.artifact_work().await {
                Ok(mut work) => {
                    if !work.is_empty() {
                        let start = artifact_offset % work.len();
                        work.rotate_left(start);
                        artifact_offset = artifact_offset.wrapping_add(2);
                    }
                    for stored in work {
                        let Ok(permit) = self.artifact_concurrency.clone().try_acquire_owned()
                        else {
                            break;
                        };
                        let id = stored.artifact.id;
                        let Ok(guard) = self.lock(id).await.try_lock_owned() else {
                            continue;
                        };
                        let worker = self.clone();
                        tasks.spawn(async move {
                            let _permit = permit;
                            let _guard = guard;
                            if let Err(error) = worker.reconcile_artifact(id).await {
                                worker.artifact_error(id, &error).await;
                                report("artifact_reconciliation_failed", &error);
                            }
                        });
                    }
                }
                Err(error) => report("artifact_work_scan_failed", &error),
            }
            tokio::select! {result = shutdown.changed()=>{if result.is_err(){break;}},_ = tokio::time::sleep(Duration::from_millis(200))=>{}}
        }
        // Allow in-flight operations to finish. Crash recovery still uses owned labels.
        let drain = async { while tasks.join_next().await.is_some() {} };
        if tokio::time::timeout(Duration::from_secs(30), drain)
            .await
            .is_err()
        {
            tasks.shutdown().await;
        }
        let ids = self
            .network_tasks
            .lock()
            .await
            .keys()
            .copied()
            .collect::<Vec<_>>();
        for id in ids {
            if let Err(error) = self.stop_network_task(id).await {
                report("network_session_shutdown_unconfirmed", &error);
            }
        }
    }

    pub async fn heartbeat(self: Arc<Self>, mut shutdown: watch::Receiver<bool>) {
        loop {
            let mut registration = self.registration.clone();
            registration.heartbeat = if *shutdown.borrow() {
                Utc::now() - chrono::Duration::seconds(60)
            } else {
                Utc::now()
            };
            if let Err(error) = self.store.register_worker(&registration).await {
                report("heartbeat_failed", &error);
            }
            if *shutdown.borrow() {
                return;
            }
            tokio::select! {result = shutdown.changed()=>{if result.is_err(){return;}},_ = tokio::time::sleep(Duration::from_secs(2))=>{}}
        }
    }

    pub async fn expire(self: Arc<Self>, mut shutdown: watch::Receiver<bool>) {
        loop {
            for driver in self.drivers.values() {
                match driver.reap_expired().await {
                    Ok(ids) => {
                        for id in ids {
                            println!(
                                "{}",
                                serde_json::json!({"event":"expired_sandbox_removed","sandbox_id":id})
                            );
                        }
                    }
                    Err(error) => report("expiry_scan_failed", &error),
                }
            }
            if *shutdown.borrow() {
                return;
            }
            tokio::select! {result = shutdown.changed()=>{if result.is_err(){return;}},_ = tokio::time::sleep(Duration::from_secs(1))=>{}}
        }
    }

    pub(super) async fn save(
        &self,
        mut stored: StoredSandbox,
        state: SandboxState,
        cleanup: CleanupState,
        reason: Option<String>,
    ) -> Result<StoredSandbox, ApiError> {
        if stored.sandbox.state != state && transition(stored.sandbox.state, state).is_err() {
            if stored.sandbox.state == SandboxState::Pending {
                stored.sandbox.state = SandboxState::Starting;
                self.store.observe(stored.clone()).await?;
            }
            if stored.sandbox.state != SandboxState::Unknown
                && transition(stored.sandbox.state, state).is_err()
            {
                transition(stored.sandbox.state, SandboxState::Unknown)?;
                stored.sandbox.state = SandboxState::Unknown;
                stored.sandbox.cleanup = CleanupState::Unknown;
                self.store.observe(stored.clone()).await?;
            }
        }
        stored.sandbox.state = state;
        stored.sandbox.cleanup = cleanup;
        stored.sandbox.observed_at = Some(Utc::now());
        stored.sandbox.reason = reason;
        let id = stored.sandbox.id;
        self.store.observe(stored).await?;
        self.store.sandbox(id).await
    }
}

fn report(event: &str, error: &ApiError) {
    eprintln!("{}", serde_json::json!({"event":event,"error":error}));
}

async fn diagnostics(
    State(worker): State<Arc<Worker>>,
    ApiJson(call): ApiJson<InternalSandboxCall>,
) -> Result<Json<SandboxDiagnostics>, HttpError> {
    let _guard = worker.lock(call.sandbox_id).await.lock_owned().await;
    let stored = worker.store.sandbox(call.sandbox_id).await?;
    worker
        .store
        .authorize_feature(call.sandbox_id, Capability::Diagnostics)
        .await?;
    let profile = worker
        .registration
        .profiles
        .iter()
        .find(|profile| profile.id == stored.sandbox.profile)
        .ok_or_else(|| {
            ApiError::new(
                ErrorCode::UnsupportedCapability,
                "sandbox profile is unavailable",
            )
        })?;
    require_capability(profile, Capability::Diagnostics)?;
    let driver = worker.drivers.get(&stored.sandbox.profile).ok_or_else(|| {
        ApiError::new(
            ErrorCode::BackendUnavailable,
            "worker has no driver for this profile",
        )
    })?;
    let runtime = if let Some(handle) = worker.recovered_handle(&stored, driver).await? {
        worker.require_network_dispatch(call.sandbox_id).await?;
        match driver.diagnostics(&handle).await {
            Ok(sample) => Some(sample),
            Err(error) if error.code == ErrorCode::NotFound => None,
            Err(error) => return Err(error.into()),
        }
    } else {
        None
    };
    Ok(Json(SandboxDiagnostics {
        sandbox: stored.sandbox,
        runtime,
    }))
}

async fn files(
    State(worker): State<Arc<Worker>>,
    ApiJson(call): ApiJson<InternalFileCall>,
) -> Result<Json<AgentResponse>, HttpError> {
    if !matches!(
        call.request,
        AgentRequest::WriteFile { .. }
            | AgentRequest::ReadFile { .. }
            | AgentRequest::ListFiles { .. }
            | AgentRequest::RemoveFile { .. }
    ) {
        return Err(ApiError::new(
            ErrorCode::Forbidden,
            "private file route rejects other agent methods",
        )
        .into());
    }
    let _guard = worker.lock(call.sandbox_id).await.lock_owned().await;
    let stored = worker.store.sandbox(call.sandbox_id).await?;
    worker
        .store
        .authorize_work(call.sandbox_id, Capability::Files)
        .await?;
    let profile = worker
        .registration
        .profiles
        .iter()
        .find(|profile| profile.id == stored.sandbox.profile)
        .ok_or_else(|| {
            ApiError::new(
                ErrorCode::UnsupportedCapability,
                "sandbox profile is unavailable",
            )
        })?;
    require_capability(profile, Capability::Files)?;
    let driver = worker.drivers.get(&stored.sandbox.profile).ok_or_else(|| {
        ApiError::new(
            ErrorCode::BackendUnavailable,
            "worker has no driver for this profile",
        )
    })?;
    let handle = stored.handle.ok_or_else(|| {
        ApiError::new(
            ErrorCode::BackendUnavailable,
            "runtime handle is not available",
        )
    })?;
    Ok(Json(worker.rpc(driver, &handle, &call.request).await?))
}

//! Deployment availability requires actual protected application and collection.
use super::*;
use base64::{Engine, engine::general_purpose::STANDARD};

fn unknown() -> ApiError {
    ApiError::new(
        ErrorCode::BackendUnavailable,
        "protected network availability or probe cleanup is unconfirmed",
    )
}

pub(super) async fn pending_heartbeat(
    store: Store,
    mut registration: WorkerRegistration,
    mut shutdown: watch::Receiver<bool>,
) -> Result<(), ApiError> {
    loop {
        if *shutdown.borrow() {
            return Ok(());
        }
        registration.heartbeat = Utc::now();
        store.register_worker(&registration).await?;
        tokio::select! {
            result = shutdown.changed() => { if result.is_err() || *shutdown.borrow() { return Ok(()); } },
            _ = tokio::time::sleep(Duration::from_secs(2)) => {},
        }
    }
}

impl Worker {
    pub(super) async fn probe_network_profiles(
        &self,
        image: &str,
    ) -> Result<Vec<RuntimeProfile>, ApiError> {
        // These durable internal roots are never adopted as user workloads,
        // including after a process dies between dispatch and acknowledgement.
        for old in self.store.network_profile_probes().await? {
            self.collect_probe_root(old.sandbox.id).await?;
            self.store
                .finish_operations(
                    old.sandbox.id,
                    "network_profile_probe",
                    OperationState::Failed,
                    Some(unknown()),
                )
                .await?;
        }
        let mut profiles = self.registration.profiles.clone();
        for profile in &mut profiles {
            if profile.availability != Availability::Available {
                continue;
            }
            let limits = ResourceLimits {
                cpu_millis: 500,
                memory_bytes: 256 * 1024 * 1024,
                pids: 64,
            };
            let mut request = CreateSandbox::new(&profile.id, image);
            request.resources = limits.clone();
            request.ttl_seconds = 300;
            if profile.capabilities.contains(&Capability::IsolatedSessions) {
                request.child_budget = Some(limits.clone());
            }
            let created = match self
                .store
                .create_network_profile_probe(profile, &request, &Uuid::new_v4().to_string())
                .await
            {
                Ok(value) => value,
                Err(error) => {
                    report("network_profile_probe_admission_failed", &error);
                    profile.availability = Availability::Unavailable;
                    profile.capabilities.remove(&Capability::NetworkPolicy);
                    profile.reason =
                        Some("protected network probe could not reserve its resources".into());
                    continue;
                }
            };
            let root = created.sandbox.id;
            self.store
                .finish_operations(root, "network_profile_probe", OperationState::Running, None)
                .await?;
            let result = self.probe_network_tree(profile, root, &limits).await;
            // A failed feature check is an unavailable profile. Unconfirmed
            // collection is a failed startup, never a successful probe.
            self.collect_probe_root(root).await?;
            self.store
                .finish_operations(
                    root,
                    "network_profile_probe",
                    if result.is_ok() {
                        OperationState::Succeeded
                    } else {
                        OperationState::Failed
                    },
                    result.as_ref().err().cloned(),
                )
                .await?;
            if let Err(error) = result {
                report("network_profile_probe_failed", &error);
                profile.availability = Availability::Unavailable;
                profile.capabilities.remove(&Capability::NetworkPolicy);
                profile.reason =
                    Some("actual protected network application failed; no runtime fallback".into());
            }
            println!(
                "{}",
                serde_json::json!({"event":"network_profile_probe_collected","profile":profile.id,"sandbox_id":root,"available":profile.availability==Availability::Available})
            );
        }
        Ok(profiles)
    }

    async fn wait_probe_ready(&self, ids: &[Uuid]) -> Result<(), ApiError> {
        let deadline = tokio::time::Instant::now() + Duration::from_secs(90);
        loop {
            let mut ready = true;
            for id in ids {
                self.reconcile(*id).await?;
                let stored = self.store.sandbox(*id).await?;
                if matches!(
                    stored.sandbox.state,
                    SandboxState::Failed | SandboxState::Terminated
                ) {
                    return Err(unknown());
                }
                ready &= stored.sandbox.state == SandboxState::Running
                    && self.require_network_dispatch(*id).await.is_ok();
            }
            if ready {
                return Ok(());
            }
            if tokio::time::Instant::now() >= deadline {
                return Err(unknown());
            }
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
    }

    async fn probe_command(&self, id: Uuid) -> Result<(), ApiError> {
        let spec: CommandSpec = serde_json::from_value(serde_json::json!({
            "argv":["/bin/sh","-c","printf goldenhoop_network_profile_probe"],"timeout_seconds":10
        }))
        .map_err(|_| unknown())?;
        let execution = self
            .store
            .create_execution(id, &spec, &Uuid::new_v4().to_string())
            .await?;
        let deadline = tokio::time::Instant::now() + Duration::from_secs(25);
        loop {
            self.reconcile(id).await?;
            let current = self.store.execution(execution.id).await?.execution;
            if current.state.is_terminal() {
                if current.state != ExecutionState::Succeeded || current.exit_code != Some(0) {
                    return Err(unknown());
                }
                let mut stdout = Vec::new();
                let mut completed = 0;
                for event in self.store.events(execution.id, 0).await? {
                    if event.kind == EventKind::Stdout {
                        stdout.extend(
                            STANDARD
                                .decode(event.data["data"].as_str().ok_or_else(unknown)?)
                                .map_err(|_| unknown())?,
                        );
                    }
                    if event.kind == EventKind::Completed {
                        completed += 1;
                    }
                }
                if stdout != b"goldenhoop_network_profile_probe" || completed != 1 {
                    return Err(unknown());
                }
                return Ok(());
            }
            if tokio::time::Instant::now() >= deadline {
                return Err(unknown());
            }
            tokio::time::sleep(Duration::from_millis(100)).await;
        }
    }

    async fn probe_network_tree(
        &self,
        profile: &RuntimeProfile,
        root: Uuid,
        limits: &ResourceLimits,
    ) -> Result<(), ApiError> {
        self.wait_probe_ready(&[root]).await?;
        let mut ids = vec![root];
        if profile.capabilities.contains(&Capability::IsolatedSessions) {
            let child = self
                .store
                .create_isolated_session(
                    profile,
                    root,
                    &CreateIsolatedSession {
                        resources: limits.clone(),
                        network: Some(NetworkPolicy {
                            default_action: NetworkAction::Deny,
                            rules: vec![NetworkRule {
                                destination: "93.184.216.34".into(),
                                ports: vec![443],
                                action: NetworkAction::Allow,
                            }],
                        }),
                        ..Default::default()
                    },
                    &Uuid::new_v4().to_string(),
                )
                .await?;
            ids.push(child.sandbox.id);
            self.wait_probe_ready(&ids).await?;
        }
        let mut original = Vec::new();
        for id in &ids {
            original.push(
                self.store
                    .sandbox(*id)
                    .await?
                    .handle
                    .ok_or_else(unknown)?
                    .backend_ref,
            );
            self.probe_command(*id).await?;
        }
        for (expected, action) in [(0, NetworkAction::Allow), (1, NetworkAction::Deny)] {
            let changed = self
                .store
                .set_public_network_policy(
                    root,
                    &SetNetworkPolicy {
                        expected_revision: expected,
                        policy: NetworkPolicy {
                            default_action: action,
                            rules: vec![],
                        },
                    },
                    &Uuid::new_v4().to_string(),
                )
                .await?;
            self.wait_probe_ready(&ids).await?;
            self.store.settle_network_policy_changes().await?;
            if self.store.operation(changed.operation.id).await?.state != OperationState::Succeeded
            {
                return Err(unknown());
            }
            for (id, physical) in ids.iter().zip(&original) {
                let policy = self.store.network_policy(*id).await?;
                if policy
                    .public_inputs
                    .as_ref()
                    .and_then(|p| p.lineage.first())
                    .map(|s| (s.sandbox_id, s.revision))
                    != Some((root, expected + 1))
                    || self
                        .store
                        .sandbox(*id)
                        .await?
                        .handle
                        .as_ref()
                        .map(|h| &h.backend_ref)
                        != Some(physical)
                {
                    return Err(unknown());
                }
                self.probe_command(*id).await?;
            }
        }
        Ok(())
    }

    async fn collect_probe_root(&self, root: Uuid) -> Result<(), ApiError> {
        self.store
            .set_desired(
                root,
                DesiredState::Terminated,
                &format!("network-probe-close-{root}"),
            )
            .await?;
        let deadline = tokio::time::Instant::now() + Duration::from_secs(100);
        loop {
            let mut members = Vec::new();
            for stored in self.store.work().await? {
                let scope = self.store.sandbox_scope(stored.sandbox.id).await?;
                if scope.root_id == root {
                    members.push((scope.depth, stored.sandbox.id));
                }
            }
            members.sort_by_key(|(depth, _)| std::cmp::Reverse(*depth));
            for (_, id) in members {
                self.reconcile(id).await?;
            }
            if self.store.sandbox(root).await?.sandbox.cleanup == CleanupState::Complete {
                return Ok(());
            }
            if tokio::time::Instant::now() >= deadline {
                return Err(unknown());
            }
            tokio::time::sleep(Duration::from_millis(200)).await;
        }
    }
}

use super::*;

impl Worker {
    pub(super) fn runtime_request(
        &self,
        stored: &StoredSandbox,
    ) -> Result<CreateSandbox, ApiError> {
        let profile = self
            .registration
            .profiles
            .iter()
            .find(|profile| profile.id == stored.request.profile)
            .ok_or_else(|| {
                ApiError::new(
                    ErrorCode::UnsupportedCapability,
                    "runtime profile is not registered",
                )
            })?;
        goldenhoop_core::validate_create(profile, &stored.request)?;
        let mut native = stored.request.clone();
        // Artifact retention is implemented by the probed host storage worker.
        // Its availability is checked above; the native driver owns file capture.
        native.required_capabilities.remove(&Capability::Artifacts);
        // Hierarchy allocation and feature ceilings are enforced by the host.
        // The native runtime receives only this node's workload hard limits.
        native
            .required_capabilities
            .remove(&Capability::IsolatedSessions);
        native.child_budget = None;
        native.feature_limit = None;
        Ok(native)
    }
    pub(super) async fn recovered_handle(
        &self,
        stored: &StoredSandbox,
        driver: &DockerDriver,
    ) -> Result<Option<RuntimeHandle>, ApiError> {
        if let Some(handle) = &stored.handle {
            return Ok(Some(handle.clone()));
        }
        Ok(driver
            .discover()
            .await?
            .into_iter()
            .find(|handle| handle.sandbox_id == stored.sandbox.id))
    }

    pub(super) async fn reconcile(&self, id: Uuid) -> Result<(), ApiError> {
        let mut stored = self.store.sandbox(id).await?;
        let driver = self
            .drivers
            .get(&stored.sandbox.profile)
            .cloned()
            .ok_or_else(|| {
                ApiError::new(
                    ErrorCode::UnsupportedCapability,
                    "worker has no matching runtime driver",
                )
            })?;
        // Only explicitly staged complete allocations enter live control.
        // Partial/legacy journals cannot fall through to none-network creation.
        match self.store.network_allocation(id).await {
            Ok(network) if stored.sandbox.desired_state != DesiredState::Terminated => {
                match self.store.network_policy(id).await {
                    Ok(_) => {
                        let driver = self
                            .drivers
                            .get(&stored.sandbox.profile)
                            .cloned()
                            .ok_or_else(|| {
                                ApiError::new(
                                    ErrorCode::UnsupportedCapability,
                                    "worker has no matching runtime driver",
                                )
                            })?;
                        return self.reconcile_network(stored, driver).await;
                    }
                    Err(error) if error.code == ErrorCode::NotFound => {}
                    Err(error) => return Err(error),
                }
                self.store
                    .set_desired(
                        id,
                        DesiredState::Terminated,
                        &format!("network-recovery-{}", network.generation),
                    )
                    .await?;
                stored = self.store.sandbox(id).await?;
            }
            Ok(_) => {}
            Err(error) if error.code == ErrorCode::NotFound => {
                if self.network_options.is_some()
                    && !stored.ever_running
                    && stored.sandbox.desired_state == DesiredState::Running
                    && !matches!(
                        stored.sandbox.state,
                        SandboxState::Failed | SandboxState::Terminated
                    )
                {
                    if stored.sandbox.state != SandboxState::Pending {
                        return self.stop(stored, &driver, "uncertain protected bootstrap has no allocation; refusing none-network creation", ExecutionState::Failed).await;
                    }
                    let profile = self
                        .registration
                        .profiles
                        .iter()
                        .find(|p| p.id == stored.sandbox.profile)
                        .ok_or_else(|| {
                            ApiError::new(
                                ErrorCode::UnsupportedCapability,
                                "protected runtime profile is absent",
                            )
                        })?;
                    require_capability(profile, Capability::NetworkPolicy)?;
                    self.bootstrap_network(stored, &driver).await?;
                    return self
                        .reconcile_network(self.store.sandbox(id).await?, driver)
                        .await;
                }
            }
            Err(error) => return Err(error),
        }
        let driver = self.drivers.get(&stored.sandbox.profile).ok_or_else(|| {
            ApiError::new(
                ErrorCode::UnsupportedCapability,
                "worker has no matching runtime driver",
            )
        })?;
        if self.store.effective_desired(id).await? == DesiredState::Terminated
            && stored.sandbox.desired_state != DesiredState::Terminated
        {
            self.store
                .set_desired(id, DesiredState::Terminated, &format!("tree-close-{id}"))
                .await?;
            stored = self.store.sandbox(id).await?;
        }
        if stored.sandbox.desired_state == DesiredState::Terminated
            || matches!(
                stored.sandbox.state,
                SandboxState::Failed | SandboxState::Terminated
            )
        {
            let state = if stored.sandbox.state == SandboxState::Failed {
                ExecutionState::Failed
            } else {
                ExecutionState::Cancelled
            };
            return self
                .stop(stored, driver, "sandbox termination requested", state)
                .await;
        }
        stored.handle = self.recovered_handle(&stored, driver).await?;
        let observation = if let Some(handle) = &stored.handle {
            Some(driver.inspect(handle).await?)
        } else {
            None
        };
        match observation.as_ref().map(|observation| observation.state) {
            None | Some(ObservedState::Missing) if !stored.ever_running => {
                // No workload command was accepted before the first durable Running
                // observation. Confirmed absence permits an idempotent create retry.
                stored.handle = None;
                stored = self
                    .save(stored, SandboxState::Starting, CleanupState::Pending, None)
                    .await?;
                self.store
                    .finish_operations(id, "create", OperationState::Running, None)
                    .await?;
                let handle = driver
                    .create(&stored.sandbox, &self.runtime_request(&stored)?)
                    .await?;
                stored.handle = Some(handle);
                self.save(stored, SandboxState::Running, CleanupState::Pending, None)
                    .await?;
                self.store
                    .finish_operations(id, "create", OperationState::Succeeded, None)
                    .await?;
                return Ok(());
            }
            None | Some(ObservedState::Missing | ObservedState::Exited) => {
                let reason = match &observation {
                    Some(observation) if observation.state == ObservedState::Exited => format!(
                        "runtime exited before a terminal result was collected; exit_code={:?}, oom_killed={:?}",
                        observation.exit_code, observation.oom_killed
                    ),
                    _ => "runtime disappeared before a terminal result was collected".into(),
                };
                return self
                    .stop(stored, driver, &reason, ExecutionState::Failed)
                    .await;
            }
            Some(ObservedState::Starting) if !stored.ever_running => {
                stored = self
                    .save(stored, SandboxState::Starting, CleanupState::Pending, None)
                    .await?;
                let handle = driver
                    .create(&stored.sandbox, &self.runtime_request(&stored)?)
                    .await?;
                stored.handle = Some(handle);
                self.save(stored, SandboxState::Running, CleanupState::Pending, None)
                    .await?;
                self.store
                    .finish_operations(id, "create", OperationState::Succeeded, None)
                    .await?;
                return Ok(());
            }
            Some(ObservedState::Starting | ObservedState::Unknown) => {
                self.save(stored,SandboxState::Unknown,CleanupState::Unknown,Some("runtime observation is uncertain; an existing workload will not be recreated".into())).await?;
                return Ok(());
            }
            Some(ObservedState::Running) => {
                stored = self
                    .save(stored, SandboxState::Running, CleanupState::Pending, None)
                    .await?;
            }
            Some(ObservedState::Paused) => {
                stored = self
                    .save(stored, SandboxState::Paused, CleanupState::Pending, None)
                    .await?;
            }
        }
        if stored.ever_running {
            self.store
                .finish_operations(id, "create", OperationState::Succeeded, None)
                .await?;
        }
        let effective = self.store.effective_desired(id).await?;
        if effective == DesiredState::Terminated {
            return self
                .stop(
                    stored,
                    driver,
                    "sandbox deadline or termination requested",
                    ExecutionState::Cancelled,
                )
                .await;
        }
        let handle = stored.handle.clone().ok_or_else(|| {
            ApiError::new(ErrorCode::BackendUnavailable, "runtime handle is absent")
        })?;
        if effective == DesiredState::Paused {
            if stored.sandbox.state != SandboxState::Paused {
                stored = self
                    .save(stored, SandboxState::Pausing, CleanupState::Pending, None)
                    .await?;
                driver.pause(&handle).await?;
                self.save(stored, SandboxState::Paused, CleanupState::Pending, None)
                    .await?;
            }
            if self.store.subtree_settled(id).await? {
                self.store
                    .finish_operations(id, "pause", OperationState::Succeeded, None)
                    .await?;
            }
            return Ok(());
        }
        if stored.sandbox.state == SandboxState::Paused {
            stored = self
                .save(stored, SandboxState::Resuming, CleanupState::Pending, None)
                .await?;
            driver.resume(&handle).await?;
            self.save(stored, SandboxState::Running, CleanupState::Pending, None)
                .await?;
        }
        self.store
            .finish_operations(id, "create", OperationState::Succeeded, None)
            .await?;
        if self.store.subtree_settled(id).await? {
            self.store
                .finish_operations(id, "resume", OperationState::Succeeded, None)
                .await?;
        }
        if !self.sync_contexts(&handle, driver).await? {
            return Ok(());
        }
        for execution in self.store.execution_work(id).await?.into_iter().take(16) {
            if self.store.effective_desired(id).await? != DesiredState::Running {
                break;
            }
            if !self.sync_execution(&handle, driver, execution).await? {
                break;
            }
        }
        Ok(())
    }

    pub(super) async fn stop(
        &self,
        mut stored: StoredSandbox,
        driver: &DockerDriver,
        reason: &str,
        execution_state: ExecutionState,
    ) -> Result<(), ApiError> {
        let id = stored.sandbox.id;
        let expired = expired(&stored.sandbox, Utc::now());
        let failed = stored.sandbox.state == SandboxState::Failed
            || execution_state == ExecutionState::Failed;
        self.stop_network_task(id).await?;
        stored.handle = self.recovered_handle(&stored, driver).await?;
        self.settle_create_dispatches(&stored, driver).await?;
        self.store.require_network_creates_settled(id).await?;
        if !matches!(
            stored.sandbox.state,
            SandboxState::Failed | SandboxState::Terminated
        ) {
            stored = self
                .save(
                    stored,
                    if failed {
                        SandboxState::Failed
                    } else {
                        SandboxState::Stopping
                    },
                    CleanupState::Pending,
                    Some(reason.into()),
                )
                .await?;
        }
        if let Some(handle) = &stored.handle {
            driver.remove(handle).await?;
        }
        stored.handle = None;
        for context in self.store.code_context_work(id).await? {
            if expired || !failed {
                self.store
                    .close_code_context(context.context.id, &format!("source-stop-{id}"))
                    .await?;
            }
            let outcome = if expired {
                CodeRunState::TimedOut
            } else if failed {
                CodeRunState::Unknown
            } else {
                CodeRunState::Cancelled
            };
            self.store
                .finish_code_context_absent_with_state(context.context.id, reason, outcome)
                .await?;
            self.context_closures
                .lock()
                .await
                .remove(&context.context.id);
        }
        for execution in self.store.execution_work(id).await? {
            self.store
                .finish_execution(
                    execution.execution.id,
                    if expired {
                        ExecutionState::TimedOut
                    } else {
                        execution_state
                    },
                    reason,
                )
                .await?;
            self.cancellations
                .lock()
                .await
                .remove(&execution.execution.id);
        }
        if !self.store.children_collected(id).await? {
            self.save(
                stored,
                if failed {
                    SandboxState::Failed
                } else {
                    SandboxState::Stopping
                },
                CleanupState::Pending,
                Some(format!("{reason}; awaiting child collection")),
            )
            .await?;
            return Ok(());
        }
        self.collect_network(&stored).await?;
        self.save(
            stored,
            if failed {
                SandboxState::Failed
            } else {
                SandboxState::Terminated
            },
            CleanupState::Complete,
            Some(reason.into()),
        )
        .await?;
        let error = Some(ApiError::new(ErrorCode::InvalidState, reason));
        for kind in ["create", "pause", "resume"] {
            self.store
                .finish_operations(id, kind, OperationState::Failed, error.clone())
                .await?;
        }
        self.store
            .finish_operations(id, "terminate", OperationState::Succeeded, None)
            .await?;
        Ok(())
    }

    pub(super) async fn record_error(&self, id: Uuid, error: &ApiError) -> Result<(), ApiError> {
        let mut stored = self.store.sandbox(id).await?;
        if stored.sandbox.cleanup == CleanupState::Complete {
            return Ok(());
        }
        if !stored.ever_running {
            match self.store.network_allocation(id).await {
                Ok(_) => {
                    let driver = self
                        .drivers
                        .get(&stored.sandbox.profile)
                        .ok_or_else(|| error.clone())?;
                    return self
                        .stop(stored, driver, &error.message, ExecutionState::Failed)
                        .await;
                }
                Err(error) if error.code == ErrorCode::NotFound => {}
                Err(error) => return Err(error),
            }
        }
        if !stored.ever_running
            && matches!(
                error.code,
                ErrorCode::InvalidRequest
                    | ErrorCode::UnsupportedCapability
                    | ErrorCode::NotFound
                    | ErrorCode::QuotaExceeded
            )
        {
            let driver = self
                .drivers
                .get(&stored.sandbox.profile)
                .ok_or_else(|| error.clone())?;
            stored.handle = self.recovered_handle(&stored, driver).await?;
            if let Some(handle) = &stored.handle {
                driver.remove(handle).await?;
            }
            stored.handle = None;
            self.save(
                stored,
                SandboxState::Failed,
                CleanupState::Complete,
                Some(error.message.clone()),
            )
            .await?;
            self.store
                .finish_operations(id, "create", OperationState::Failed, Some(error.clone()))
                .await?;
            self.store
                .finish_operations(id, "terminate", OperationState::Succeeded, None)
                .await?;
        } else {
            let state = if stored.sandbox.state == SandboxState::Failed {
                SandboxState::Failed
            } else {
                SandboxState::Unknown
            };
            self.save(
                stored,
                state,
                CleanupState::Unknown,
                Some(error.message.clone()),
            )
            .await?;
        }
        Ok(())
    }
}
